getOrderStatusList() {
  const originalList = this.$commonData.ORDER_ORDERHEADERSTATUS || []
  const statusMap = {}
  originalList.forEach(item => {
    statusMap[item.value] = item
  })

  // 构建排序后的新列表
  const sortedList = []

  // 先按固定顺序添加特定状态
  ['1', '2'].forEach(value => {
    if (statusMap[value]) {
      sortedList.push(statusMap[value])
    }
  })

  // 插入状态 7 (已受理)
  if (statusMap['7']) {
    sortedList.push(statusMap['7'])
  }

  // 添加剩余状态（除2和7之外的其他状态），保持原有相对顺序
  originalList.forEach(item => {
    if (item.value !== '2' && item.value !== '7') {
      if (!['1', '2', '7'].includes(item.value) && statusMap[item.value]) {
        sortedList.push(statusMap[item.value])
      }
    }
  })

  return sortedList
},

